"""FD solver for Test Problem 1 with weights generated by a neural network.

Same discretization as PHS_fd_TP1.m (solver = 'FD'):
  unknowns u+ at X+ = [Xint+; Xbd+; XG] and u- at X- = [Xint-; Xbd-; XG],
  rows: -alpha+ Lap u+ = f (Xint+), -alpha- Lap u- = f (Xint-), u = g (dOmega),
        u+ - u- = phi (XG), alpha+ dn u+ - alpha- dn u- = psi (XG).
  Stencil of a row at x: the nloc nearest nodes of the same side.

Weights of one stencil (scaled coordinates y_hat = (y - x)/r, r = stencil radius):
    w_hat = w0 + (I - Pi) v,   w0 = P (P'P)^-1 Lp,   Pi = orthogonal projector onto range(P),
  P = polynomials of degree <= deg at the stencil nodes, v = network output.
  P' w_hat = Lp for every v: the weights are exact on the polynomials of degree <= deg.

Loss (Davydov & Schaback, eq. (20), plus the error of the discrete solution):
    L = ||A^-1 b - U*||^2 / ||U*||^2 + lam * mean_i sum_j |w_hat_ij| ||y_hat_j||^mu
"""

import time

import numpy as np
import scipy.sparse as sp
import scipy.sparse.linalg as spla
import torch
from scipy.spatial import cKDTree

from nodes_TP1 import nodes_TP1

torch.set_default_dtype(torch.float64)

# Exact solution and data of Test Problem 1
AP, AM = 20.0, 1.0                                   # alpha+ (y > 2x^3), alpha- (y < 2x^3)
s_ = lambda x, y: y - 2 * x**3
up = lambda x, y: (s_(x, y)**2 - 30 * s_(x, y)) / 20
um = lambda x, y: s_(x, y)**2 - 30 * s_(x, y)
lapq = lambda x, y: 2 * (36 * x**4 + 1) - 12 * x * (2 * s_(x, y) - 30)        # Lap(s^2 - 30 s)
f = lambda x, y: -lapq(x, y)                                                   # f = -alpha Lap u
gradq = lambda x, y: np.column_stack([(2 * s_(x, y) - 30) * (-6 * x**2), 2 * s_(x, y) - 30])


def normal(x):
    """Unit normal on Gamma at abscissa x, pointing into Omega+."""
    n = np.column_stack([-6 * x**2, np.ones_like(x)])
    return n / np.sqrt(1 + 36 * x**4)[:, None]


def monomials(deg):
    ea, eb = [], []
    for t in range(deg + 1):
        for b in range(t + 1):
            ea.append(t - b), eb.append(b)
    return np.array(ea), np.array(eb)


class StencilNet(torch.nn.Module):
    """MLP: scaled stencil coordinates (n nodes, sorted by distance) -> v in R^n.
    For the flux rows the coordinates are taken in the frame (normal, tangent)."""

    def __init__(self, n, width=128):
        super().__init__()
        self.mlp = torch.nn.Sequential(torch.nn.Linear(2 * n, width), torch.nn.Tanh(),
                                       torch.nn.Linear(width, width), torch.nn.Tanh(),
                                       torch.nn.Linear(width, n))

    def forward(self, Y):
        return self.mlp(Y.reshape(Y.shape[0], -1))


def make_nets(deg, nloc=None, width=128):
    """One network for the Laplacian rows, one for the normal-derivative rows."""
    Q = (deg + 1) * (deg + 2) // 2
    n = 3 * Q if nloc is None else nloc
    return torch.nn.ModuleDict({"lap": StencilNet(n, width), "dn": StencilNet(n, width)})


def _stencils(X, irows, n, op, deg, nvec=None):
    """Stencils of the rows at X[irows]: indices, scaled coordinates, radius, w0 and Q (range(P))."""
    _, idx = cKDTree(X).query(X[irows], k=n)
    Y = X[idx] - X[irows][:, None, :]
    r = np.sqrt((Y**2).sum(2)).max(1)
    Yh = Y / r[:, None, None]
    ea, eb = monomials(deg)
    P = Yh[:, :, 0:1]**ea * Yh[:, :, 1:2]**eb                          # (B,n,Q)
    Lp = np.zeros((len(irows), len(ea)))
    if op == "lap":
        Lp[:, (ea == 2) & (eb == 0)] = 2.0
        Lp[:, (ea == 0) & (eb == 2)] = 2.0
        feat = Yh
    else:
        Lp[:, (ea == 1) & (eb == 0)] = nvec[:, 0:1]
        Lp[:, (ea == 0) & (eb == 1)] = nvec[:, 1:2]
        yn = Yh[:, :, 0] * nvec[:, None, 0] + Yh[:, :, 1] * nvec[:, None, 1]
        yt = -Yh[:, :, 0] * nvec[:, None, 1] + Yh[:, :, 1] * nvec[:, None, 0]
        feat = np.stack([yn, yt], 2)
    Qm, Rm = np.linalg.qr(P)                                           # P = Q R
    w0 = np.einsum("bnq,bq->bn", Qm, np.linalg.solve(np.transpose(Rm, (0, 2, 1)), Lp[:, :, None])[:, :, 0])
    T = lambda a: torch.tensor(a)
    return dict(op=op, idx=T(idx), Yfeat=T(feat), rr=T(np.sqrt((Yh**2).sum(2))),
                r=T(r), w0=T(w0), Q=T(Qm), k=2 if op == "lap" else 1)


def assemble(nd, deg, nloc, nets, mu):
    """Triplets of the system matrix (torch, differentiable in the network parameters),
    right-hand side b, exact nodal values U*, and the eq. (20) term rho."""
    Q = (deg + 1) * (deg + 2) // 2
    nloc = 3 * Q if nloc is None else nloc
    Xp = np.vstack([nd["Xint_p"], nd["Xbd_p"], nd["XG"]])
    Xm = np.vstack([nd["Xint_m"], nd["Xbd_m"], nd["XG"]])
    nIp, nIm = len(nd["Xint_p"]), len(nd["Xint_m"])
    nBp, nBm, nG = len(nd["Xbd_p"]), len(nd["Xbd_m"]), len(nd["XG"])
    Np, Nm = len(Xp), len(Xm)
    N = Np + Nm
    iGp = nIp + nBp + np.arange(nG)
    iGm = nIm + nBm + np.arange(nG)
    xg = nd["XG"]
    nG_ = normal(xg[:, 0])
    nsp, nsm = min(nloc, Np), min(nloc, Nm)

    I, J, V, rho = [], [], [], []
    row = 0
    # derivative rows: (side nodes, row points, op, column offset, row offset, coefficient)
    r0 = nIp + nIm + nBp + nBm + nG                                    # first flux row
    groups = [(Xp, np.arange(nIp), "lap", 0, 0, -AP, nsp, None),
              (Xm, np.arange(nIm), "lap", Np, nIp, -AM, nsm, None),
              (Xp, iGp, "dn", 0, r0, AP, nsp, nG_),
              (Xm, iGm, "dn", Np, r0, -AM, nsm, nG_)]
    for X, irows, op, c0, rw0, coef, n, nv in groups:
        g = _stencils(X, irows, n, op, deg, nv)
        # network correction; if the side has fewer than nloc nodes (coarse levels) the
        # stencil is smaller than the network input and only w0 is used
        v = nets[op](g["Yfeat"]) if n == nets[op].mlp[0].in_features // 2 else torch.zeros_like(g["w0"])
        Qm = g["Q"]
        wh = g["w0"] + v - torch.einsum("bnq,bq->bn", Qm, torch.einsum("bnq,bn->bq", Qm, v))
        w = coef * wh / g["r"][:, None]**g["k"]
        I.append(torch.tensor(rw0 + np.arange(len(irows)))[:, None].expand_as(w).reshape(-1))
        J.append((c0 + g["idx"]).reshape(-1))
        V.append(w.reshape(-1))
        rho.append((wh.abs() * g["rr"]**mu).sum(1))
    # Dirichlet rows and jump rows
    row = nIp + nIm
    kb = np.r_[nIp + np.arange(nBp), Np + nIm + np.arange(nBm)]
    rb = row + np.arange(nBp + nBm)
    rj = row + nBp + nBm + np.arange(nG)
    I.append(torch.tensor(np.r_[rb, rj, rj]))
    J.append(torch.tensor(np.r_[kb, iGp, Np + iGm]))
    V.append(torch.tensor(np.r_[np.ones(len(kb)), np.ones(nG), -np.ones(nG)]))

    b = np.r_[f(Xp[:nIp, 0], Xp[:nIp, 1]), f(Xm[:nIm, 0], Xm[:nIm, 1]),
              up(Xp[nIp:nIp + nBp, 0], Xp[nIp:nIp + nBp, 1]), um(Xm[nIm:nIm + nBm, 0], Xm[nIm:nIm + nBm, 1]),
              up(xg[:, 0], xg[:, 1]) - um(xg[:, 0], xg[:, 1]),
              AP * ((gradq(xg[:, 0], xg[:, 1]) / 20) * nG_).sum(1) - AM * (gradq(xg[:, 0], xg[:, 1]) * nG_).sum(1)]
    U = np.r_[up(Xp[:, 0], Xp[:, 1]), um(Xm[:, 0], Xm[:, 1])]
    interior = np.r_[np.arange(nIp), Np + np.arange(nIm)]
    return torch.cat(I), torch.cat(J), torch.cat(V), N, b, U, interior, torch.cat(rho).mean()


def train_TP1(nets, m, deg, nloc=None, ntype="uniform", lam=0.1, mu=None, steps=500, lr=1e-3, log=50):
    """Train the networks on the node set X^(m) of Test Problem 1:
    L = ||A^-1 b - U*||^2/||U*||^2 + lam * mean_i sum_j |w_hat_ij| ||y_hat_j||^mu."""
    mu = deg if mu is None else mu
    nd = nodes_TP1(m, ntype)
    opt = torch.optim.Adam(nets.parameters(), lr=lr)
    hist = []
    for it in range(steps + 1):
        I, J, V, N, b, U, _, rho = assemble(nd, deg, nloc, nets, mu)
        A = torch.zeros(N, N).index_put((I, J), V, accumulate=True)
        U = torch.tensor(U)
        e = (torch.linalg.solve(A, torch.tensor(b)) - U).pow(2).sum() / U.pow(2).sum()
        loss = e + lam * rho
        hist.append((float(loss), float(e), float(rho)))
        if it % log == 0:
            print(f"step {it:5d}  loss {float(loss):.4e}  error term {float(e):.4e}  eq.(20) term {float(rho):.4e}")
        if it == steps:
            break
        opt.zero_grad()
        loss.backward()
        opt.step()
    return hist


@torch.no_grad()
def learned_fd_TP1(m, deg, nets, nloc=None, ntype="uniform", do_sigma=True, mu=None):
    """Solve Test Problem 1 on X^(m) with the network weights (as PHS_fd_TP1.m).
    Errors: rms and max over the interior nodes; sigma = condest(A')/norm(A,inf)."""
    mu = deg if mu is None else mu
    t0 = time.time()
    nd = nodes_TP1(m, ntype)
    I, J, V, N, b, U, interior, _ = assemble(nd, deg, nloc, nets, mu)
    A = sp.csc_matrix((V.numpy(), (I.numpy(), J.numpy())), shape=(N, N))
    u = spla.spsolve(A, b)
    t = time.time() - t0
    e = np.abs(u - U)
    out = dict(h=nd["h"], Nint=nd["Nint"], rms=np.sqrt(np.mean(e[interior]**2)), max=e[interior].max(),
               sigma=np.nan, nnz_row=A.nnz / N, time=t, u=u, err=e,
               X=np.vstack([nd["Xint_p"], nd["Xbd_p"], nd["XG"], nd["Xint_m"], nd["Xbd_m"], nd["XG"]]))
    if do_sigma:
        lu = spla.splu(A)
        op = spla.LinearOperator(A.shape, matvec=lambda x: lu.solve(x, trans="T"), rmatvec=lu.solve)
        out["sigma"] = spla.onenormest(op)                         # ||A^-T||_1 = ||A^-1||_inf
    return out
